import{z as n,x as o,o as m,c as p,q as t,j as E,D as e,d as A,s,S as i}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"股权溢价之谜","description":"","frontmatter":{"title":"股权溢价之谜","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/equity-premium-puzzle.md","filePath":"econ/equity-premium-puzzle.md","lastUpdated":1791413859000}'),l={name:"econ/equity-premium-puzzle.md"};function c(B,a,h,g,d,u){const r=o("Mermaid");return m(),p("div",null,[a[2]||(a[2]=t('<h1 id="股权溢价之谜" tabindex="-1">股权溢价之谜 <a class="header-anchor" href="#股权溢价之谜" aria-label="Permalink to &quot;股权溢价之谜&quot;">​</a></h1><div class="epigraph"><p>用观测到的消费增长去生成随机折现因子，要匹配股票对国债的超额，需要的风险厌恶远高于其他证据所能接受的。</p><footer>—— Mehra and Prescott, The Equity Premium: A Puzzle, Journal of Monetary Economics 1985</footer></div><p>定位：<a href="/econ/hansen-jagannathan">上一课</a>。HJ 界已经要求 \\(\\sigma(m)\\) 不能低于可交易夏普所暗示的水平。本课缺口是把代表性消费者的 \\(m=\\beta u&#39;(c_{t+1})/u&#39;(c_t)\\) 放进这道界：消费增长太平，除非相对风险厌恶极大。不重推 Cauchy–Schwarz，不把谜写成「股市永远涨」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/consumption-euler">跨期欧拉</a>给出资产定价核。CRRA 下 \\(u&#39;(c)=c^{-\\gamma}\\)，于是 \\(m\\) 的波动大约是 \\(\\gamma\\) 乘以消费增长的波动。美国人均消费增长的标准差远小于股票超额收益的标准差；股票相对短期国债的平均超额又很大。Mehra 与 Prescott（1985）在 Lucas 树经济里校准：要同时匹配无风险利率与股权溢价，\\(\\gamma\\) 会落到两位数，与微观、与无风险利率之谜（高 \\(\\gamma\\) 会把 \\(r_f\\) 推得太高，除非再调时间偏好）冲突。</p><p>缺口是 HJ 的会计翻译成偏好语言：夏普要求 \\(\\sigma(m)\\) 大，消费路径给不出这么大的 \\(\\sigma(m)\\)，除非 \\(\\gamma\\) 大得难以置信。这是代表性主体、时间可分 CRRA、用总量消费当 \\(c\\) 的失败，不是对「存在 \\(m\\)」的否证。</p><p><span class="marginnote">术语翻译：相对风险厌恶 \\(\\gamma\\) 说的是「消费缩水时痛苦放大的倍数」。消费跌 1%、你的边际效用痛苦放大 \\(\\gamma\\) 倍——微观实验与行为证据通常只敢接受个位数（1 到 5 左右）；下面会看到，匹配历史溢价需要它涨到几十。</span></p><p><span class="marginnote">无风险利率之谜是孪生兄弟：高 \\(\\gamma\\) 使预防性储蓄强，压低 \\(r_f\\)；要再匹配水平，往往需要 \\(\\beta\\gt 1\\) 或负的时间偏好。Weil 把两谜并读。本课以溢价为主，利率只作为同一核的另一约束。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>代表性主体、完全市场、外生消费（或 Lucas 树的股息等于消费）。股权是对总消费的要求权，国债近似无风险。欧拉给出</p> \\[\\mathrm{E}[R^e] \\approx \\gamma\\,\\mathrm{Cov}(\\Delta c, R^e) \\]<p>（对数近似）。消费与股票回报的协方差受 \\(\\sigma(\\Delta c)\\) 限制，历史 \\(\\sigma(\\Delta c)\\) 小，于是要么溢价小，要么 \\(\\gamma\\) 大。Mehra–Prescott 用马尔可夫消费增长匹配一阶与二阶矩，把「大」写成明确的校准：常规 \\(\\gamma\\) 产生的溢价只有几个基点到很小的百分数，与历史股权溢价不在同一量级。</p><p>HJ 语言更短：历史夏普要求 \\(\\sigma(m)/\\mathrm{E}[m]\\) 高；CRRA 的 \\(\\sigma(m)\\approx\\gamma\\sigma(\\Delta c)\\)，观测到的 \\(\\sigma(\\Delta c)\\) 把 \\(\\gamma\\) 顶上去。两句话是同一缺口。</p>',13)),(m(),E(i,null,{default:e(()=>[s(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20SH%5B%22%E9%AB%98%E5%A4%8F%E6%99%AE%22%5D%20--%3E%20HJ%5B%22HJ%3A%20sigma(m)%20%E5%BF%85%E9%A1%BB%E5%A4%A7%22%5D%0A%20%20CRRA%5B%22m%20%E9%9A%8F%20c%20%E7%9A%84%E8%BE%B9%E9%99%85%E6%9B%BF%E4%BB%A3%22%5D%20--%3E%20SIG%5B%22sigma(m)%20~%20gamma%20*%20sigma(Delta%20c)%22%5D%0A%20%20CONS%5B%22%E8%A7%82%E6%B5%8B%3A%20sigma(Delta%20c)%20%E5%B0%8F%22%5D%20--%3E%20SIG%0A%20%20HJ%20--%3E%20G%5B%22%E9%9C%80%E8%A6%81%E5%BE%88%E5%A4%A7%E7%9A%84%20gamma%22%5D%0A%20%20SIG%20--%3E%20G%0A%20%20G%20--%3E%20PUZ%5B%22%E4%B8%8E%E5%85%B6%E4%BB%96%E8%AF%81%E6%8D%AE%E5%86%B2%E7%AA%81%3A%20%E8%B0%9C%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">数字实例：美国历史股票年超额约 6 个百分点、波动约 15%—20%，夏普比率约 0.4，于是 HJ 要求 \\(\\sigma(m)/\\mathrm{E}[m]\\gtrsim 0.4\\)；而总量消费增长的标准差约 1%，CRRA 给出 \\(\\sigma(m)/\\mathrm{E}[m]\\approx\\gamma\\times 1\\%\\)。两头一夹，\\(\\gamma\\) 得到 40 上下——谜就是这道除法。</span></p><p>候选出路（习惯、长期风险、罕见灾难、不完全市场）都是改 \\(m\\) 的形状或改谁的 \\(c\\) 进 \\(m\\)，不是改 HJ 会计。本课不展开修补菜单。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是总量消费作为边际价值的代理太平滑。家庭层面的消费更抖，但不能自动进 \\(m\\)：能被保险的特异风险在完全市场里被消掉，剩下的共同部分才定价。若市场不完全，特异风险可以进入个别欧拉，加总消费不再是正确的 \\(c\\)——那是另一模型，不是 Mehra–Prescott 的设定。谜首先判决的是「用总量 \\(c\\) 的 CRRA 代表性主体」。</p><p>股权溢价是对「在消费差的时候仍必须持有总风险」的补偿。总量消费差得不够多，补偿就不够大。股票价格波动本身很大，但若这些波动不与 \\(c\\) 对齐，进不了 \\(m\\)。这就是「与 \\(m\\) 的协方差，不是方差」在宏观数据上的刺。</p><h3 id="谜不是-capm-横截面" tabindex="-1">谜不是 CAPM 横截面 <a class="header-anchor" href="#谜不是-capm-横截面" aria-label="Permalink to &quot;谜不是 CAPM 横截面&quot;">​</a></h3><p>Mehra–Prescott 比较的是股票与国债的<strong>时间序列溢价</strong>，不是个股 beta 的斜率。市场 CAPM 可以在截面上失败或成功，与这个谜独立：它可以有一个够大的 \\(\\mathrm{E}[R_m]-r_f\\)，却仍然没有消费解释。截面与因子见 <a href="/quant/capm">/quant/capm</a>；本课禁止用 Fama–French 表改写 1985 年的校准。后课 <a href="/econ/ccapm">CCAPM</a> 把同一 \\(m\\) 写成消费 beta，实证薄弱仍换栏。</p>',7)),(m(),E(i,null,{default:e(()=>[s(r,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E4%B8%A4%E5%9C%BA%E4%BA%92%E4%B8%8D%E6%9B%BF%E4%BB%A3%E7%9A%84%E6%A3%80%E9%AA%8C%22%7D%0A%20%20TS%5B%22%E6%97%B6%E9%97%B4%E5%BA%8F%E5%88%97%3A%20%E8%82%A1%E7%A5%A8%E8%B6%85%E9%A2%9D%20vs%20%E5%9B%BD%E5%80%BA%22%5D%20--%3E%20MP%5B%22Mehra-Prescott%20%E7%9A%84%E8%B0%9C%22%5D%0A%20%20XS%5B%22%E6%A8%AA%E6%88%AA%E9%9D%A2%3A%20%E6%8C%89%20beta%20%E6%8E%92%E5%BA%8F%E7%9A%84%E6%96%9C%E7%8E%87%22%5D%20--%3E%20CAPM%5B%22CAPM%20%E6%88%AA%E9%9D%A2%E6%88%90%E8%B4%A5%22%5D%0A%20%20MP%20--%3E%20FAIL%5B%22%E8%A2%AB%E5%88%A4%E5%86%B3%E7%9A%84%E6%98%AF%20m%20%E6%AD%A3%E6%AF%94%20c%5E-gamma%20%E7%9A%84%E7%89%B9%E5%8C%96%22%5D%0A%20%20CAPM%20--%3E%20INDEP%5B%22%E4%B8%A4%E5%9C%BA%E6%A3%80%E9%AA%8C%E4%BA%92%E4%B8%8D%E5%88%A4%E5%86%B3%E5%AF%B9%E6%96%B9%22%5D%0A%20%20FAIL%20--%3E%20KEEP%5B%22%E5%AD%98%E5%9C%A8%20m%20%E6%9C%AC%E8%BA%AB%E4%BB%8D%E7%84%B6%E6%88%90%E7%AB%8B%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">直觉类比：时间序列溢价问「股票这张票整体比国债多赚多少才讲得通」，横截面 CAPM 问「股票之间按风险排序的价差对不对」。一个像问「这行生意值不值得干」，另一个像问「行内哪个岗位工资排得对」——答案互不锁定。</span></p><p><span class="marginnote">样本起点、生存偏差、事先溢价是否等于事后均值，都会改变「谜有多大」。Mehra–Prescott 的定性结论对常规 CRRA 足够稳：量级对不上。本课不争论基点。</span></p><p><span class="marginnote">常见误区：「股票上蹿下跳，所以理应拿高溢价」——定价看的不是波动本身，而是与消费的协方差。一只收益再颠簸、却总在消费平稳时才亏钱的资产，在 \\(m\\) 语言里几乎无风险，溢价近似为零。方差进不了价，协方差才进价。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把谜写成「股票风险被误定价，快买」。它可以是模型错、也可以是灾难风险被样本低估。也不要把高 \\(\\gamma\\) 当成已经接受的偏好参数——那会与无风险利率、与微观风险厌恶一起炸。本课停留在：总量 CRRA 核进不了 HJ 可行域，除非 \\(\\gamma\\) 离谱。</p><p>后课默认：股权溢价之谜是消费核的波动不够。存在 \\(m\\) 仍然成立；失败的是 \\(m\\propto c^{-\\gamma}\\) 这一特化。消费 CAPM 后课把特化写成 beta 语言。</p><p>代表性主体加平滑的 \\(c\\)，给不出股票债券的夏普。这是偏好与加总的失败，不是信息分层的失败。</p><p>习惯形成与长期风险改的是 \\(m\\) 对哪一段消费敏感。那是修补，不是 1985 年的谜本身。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HJ 要求 \\(\\sigma(m)\\) 大；CRRA 的 \\(\\sigma(m)\\) 被 \\(\\sigma(\\Delta c)\\) 限制。</li><li>Mehra–Prescott：常规风险厌恶产生不了历史股权溢价。</li><li>谜针对总量消费核，不自动否定有效，也不等于 CAPM 截面检验。</li><li>出处：Mehra and Prescott, <em>JME</em> 1985；Hansen–Jagannathan 界为会计入口。</li></ul>',10))])}const P=n(l,[["render",c]]);export{C as __pageData,P as default};
